// Analytics service for logging page views
// This service will be used in server components for non-blocking analytics

interface PageViewData {
  page: string;
  timestamp: number;
  userAgent?: string;
  referrer?: string;
}

export class AnalyticsService {
  private endpoint: string;
  private apiKey?: string;

  constructor(endpoint: string, apiKey?: string) {
    this.endpoint = endpoint;
    this.apiKey = apiKey;
  }

  async logPageView(data: PageViewData): Promise<void> {
    try {
      // Simulate network request to analytics service
      const response = await fetch(this.endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(this.apiKey && { 'Authorization': `Bearer ${this.apiKey}` })
        },
        body: JSON.stringify(data)
      });

      if (!response.ok) {
        console.warn('Analytics logging failed:', response.status);
      }
    } catch (error) {
      console.warn('Analytics logging error:', error);
    }
  }
}

// Create analytics service instance
export const analytics = new AnalyticsService(
  process.env.ANALYTICS_ENDPOINT || 'https://analytics.example.com/pageview',
  process.env.ANALYTICS_API_KEY
);

// Function to schedule analytics logging after response is sent
// This uses Next.js's recommended approach for non-blocking operations
export function scheduleAnalytics(page: string, userAgent?: string, referrer?: string) {
  // Use setTimeout with 0 delay to schedule the analytics call
  // This ensures the response is sent first before the analytics request is made
  setTimeout(() => {
    analytics.logPageView({
      page,
      timestamp: Date.now(),
      userAgent,
      referrer
    }).catch(error => {
      console.warn('Analytics scheduling failed:', error);
    });
  }, 0);
}

'use client';

// Client-side analytics hook that works with server-side scheduling
// This allows us to capture client-specific data like user agent and referrer

import { useEffect } from 'react';
import { scheduleAnalytics } from '../lib/analytics';

interface UsePageViewAnalyticsProps {
  page: string;
}

export function usePageViewAnalytics({ page }: UsePageViewAnalyticsProps) {
  useEffect(() => {
    // Schedule analytics on the client side to capture client-specific data
    scheduleAnalytics(
      page,
      window.navigator.userAgent,
      document.referrer
    );
  }, [page]);
}

