import { describe, it, expect, vi, beforeEach } from 'vitest';
import { AnalyticsService, scheduleAnalytics } from '../app/lib/analytics';

// Mock fetch globally
global.fetch = vi.fn();

describe('Analytics Service', () => {
  let analytics: AnalyticsService;

  beforeEach(() => {
    vi.clearAllMocks();
    analytics = new AnalyticsService('https://analytics.example.com/pageview', 'test-api-key');
  });

  it('should create analytics service with correct endpoint', () => {
    expect(analytics).toBeInstanceOf(AnalyticsService);
  });

  it('should log page view successfully', async () => {
    (global.fetch as any).mockResolvedValueOnce({
      ok: true,
      status: 200
    });

    await analytics.logPageView({
      page: '/',
      timestamp: Date.now(),
      userAgent: 'test-agent',
      referrer: 'test-referrer'
    });

    expect(global.fetch).toHaveBeenCalledWith(
      'https://analytics.example.com/pageview',
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer test-api-key'
        },
        body: JSON.stringify({
          page: '/',
          timestamp: expect.any(Number),
          userAgent: 'test-agent',
          referrer: 'test-referrer'
        })
      }
    );
  });

  it('should handle analytics endpoint without API key', async () => {
    const analyticsNoAuth = new AnalyticsService('https://analytics.example.com/pageview');

    (global.fetch as any).mockResolvedValueOnce({
      ok: true,
      status: 200
    });

    await analyticsNoAuth.logPageView({
      page: '/',
      timestamp: Date.now()
    });

    expect(global.fetch).toHaveBeenCalledWith(
      'https://analytics.example.com/pageview',
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          page: '/',
          timestamp: expect.any(Number)
        })
      }
    );
  });
});

describe('scheduleAnalytics', () => {
  it('should schedule analytics with setTimeout', () => {
    const setTimeoutSpy = vi.spyOn(global, 'setTimeout');

    scheduleAnalytics('/', 'test-agent', 'test-referrer');

    expect(setTimeoutSpy).toHaveBeenCalledWith(
      expect.any(Function),
      0
    );

    setTimeoutSpy.mockRestore();
  });
});

